"""Write packages/shared/generated/policy_tables.json: the transition table and the
encouragement variants, so the offline TypeScript policy reads the same data as Python.

    PYTHONPATH=. python scripts/write_policy_tables.py
"""

from __future__ import annotations

import json

from app.orchestrator.encouragement import VARIANTS
from app.orchestrator.transitions import TRANSITIONS
from app.registries.paths import repo_root


def tables() -> dict:
    return {
        "note": "Generated by apps/api/scripts/write_policy_tables.py. Do not edit.",
        "transitions": [
            [t.rule_id, t.state_before, t.event, t.state_after, t.action] for t in TRANSITIONS
        ],
        "encouragement_variants": {k: list(v) for k, v in VARIANTS.items()},
    }


def target():
    return repo_root() / "packages" / "shared" / "generated" / "policy_tables.json"


def main() -> None:
    target().write_text(json.dumps(tables(), indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {target()}")


if __name__ == "__main__":
    main()
